-- Authority-owned SQLite schema. Decimal values are canonical TEXT, USD money INTEGER.
-- STRICT tables reject SQLite's silent numeric/string coercion at persistence boundaries.
CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY, checksum TEXT NOT NULL, recorded_at_us INTEGER NOT NULL) STRICT;
CREATE TABLE accounts(
 account_id TEXT PRIMARY KEY CHECK(length(account_id) BETWEEN 1 AND 256), venue TEXT NOT NULL,
 mode TEXT NOT NULL CHECK(mode IN ('paper','shadow','live')), quote_currency TEXT NOT NULL CHECK(quote_currency='USD'),
 created_at_us INTEGER NOT NULL CHECK(created_at_us>=0), generation INTEGER NOT NULL CHECK(generation>=0)) STRICT;
CREATE TABLE release_bundles(release_hash TEXT PRIMARY KEY CHECK(length(release_hash)=64),manifest_json TEXT NOT NULL CHECK(json_valid(manifest_json)),parent_hash TEXT REFERENCES release_bundles(release_hash),expires_at_us INTEGER NOT NULL CHECK(expires_at_us>=0),recorded_at_us INTEGER NOT NULL) STRICT;
CREATE TABLE reconciliations(reconcile_id TEXT PRIMARY KEY,account_id TEXT NOT NULL REFERENCES accounts(account_id),started_at_us INTEGER NOT NULL,finished_at_us INTEGER,venue_cursor TEXT,status TEXT NOT NULL CHECK(status IN ('pending','completed','rejected')),balances_json TEXT NOT NULL CHECK(json_valid(balances_json)),open_orders_json TEXT NOT NULL CHECK(json_valid(open_orders_json)),differences_json TEXT NOT NULL CHECK(json_valid(differences_json)),recorded_at_us INTEGER NOT NULL,CHECK(finished_at_us IS NULL OR finished_at_us>=started_at_us)) STRICT;
CREATE TABLE account_control(account_id TEXT PRIMARY KEY REFERENCES accounts(account_id),permit TEXT NOT NULL CHECK(permit IN ('none','entry','reduce_only')),permit_epoch INTEGER NOT NULL CHECK(permit_epoch>=0),hard_killed INTEGER NOT NULL CHECK(hard_killed IN (0,1)),drawdown_latched INTEGER NOT NULL CHECK(drawdown_latched IN (0,1)),daily_halted INTEGER NOT NULL CHECK(daily_halted IN (0,1)),crisis_halted INTEGER NOT NULL CHECK(crisis_halted IN (0,1)),halt_reason TEXT,lease_boot_id TEXT,lease_deadline_mono_ns INTEGER CHECK(lease_deadline_mono_ns>=0),active_release_hash TEXT REFERENCES release_bundles(release_hash),reconcile_id TEXT REFERENCES reconciliations(reconcile_id),version INTEGER NOT NULL CHECK(version>=0),updated_at_us INTEGER NOT NULL) STRICT;
-- Readiness is an explicitly mutable projection supplied by reconciler/accounting, never inferred from uptime.
CREATE TABLE account_readiness(account_id TEXT PRIMARY KEY REFERENCES accounts(account_id),ready INTEGER NOT NULL DEFAULT 0 CHECK(ready IN (0,1)),private_heartbeat_us INTEGER,valuation_version INTEGER NOT NULL DEFAULT 0 CHECK(valuation_version>=0),version INTEGER NOT NULL DEFAULT 0 CHECK(version>=0)) STRICT;
CREATE TABLE control_events(event_id TEXT PRIMARY KEY,account_id TEXT NOT NULL REFERENCES accounts(account_id),request_id TEXT NOT NULL UNIQUE,permit_epoch INTEGER NOT NULL CHECK(permit_epoch>=0),kind TEXT NOT NULL CHECK(kind IN ('arm','disarm','hard_kill','renew','clear_daily','activate_release','recovery','risk_halt','review')),actor TEXT NOT NULL,reason TEXT NOT NULL,recorded_at_us INTEGER NOT NULL) STRICT;
CREATE TABLE source_events(event_id TEXT PRIMARY KEY,source TEXT NOT NULL,stream TEXT NOT NULL,logical_key TEXT NOT NULL,revision INTEGER NOT NULL CHECK(revision>=0),instrument TEXT,event_at_us INTEGER NOT NULL,received_at_us INTEGER NOT NULL,known_at_us INTEGER NOT NULL,sequence INTEGER,block_hash TEXT,supersedes_id TEXT REFERENCES source_events(event_id),payload_json TEXT NOT NULL CHECK(json_valid(payload_json)),payload_hash TEXT NOT NULL CHECK(length(payload_hash)=64),recorded_at_us INTEGER NOT NULL,UNIQUE(source,stream,logical_key,revision),CHECK(known_at_us>=received_at_us)) STRICT;
CREATE TABLE source_invalidations(invalidation_id TEXT PRIMARY KEY,event_id TEXT NOT NULL REFERENCES source_events(event_id),known_at_us INTEGER NOT NULL,reason TEXT NOT NULL,recorded_at_us INTEGER NOT NULL) STRICT;
CREATE TABLE event_segments(segment_hash TEXT PRIMARY KEY CHECK(length(segment_hash)=64),source TEXT NOT NULL,instrument TEXT NOT NULL,first_sequence INTEGER NOT NULL,last_sequence INTEGER NOT NULL,event_from_us INTEGER NOT NULL,event_to_us INTEGER NOT NULL,received_from_us INTEGER NOT NULL,received_to_us INTEGER NOT NULL,checkpoint_hash TEXT NOT NULL CHECK(length(checkpoint_hash)=64),byte_length INTEGER NOT NULL CHECK(byte_length>0),storage_key TEXT NOT NULL,committed_at_us INTEGER NOT NULL,recorded_at_us INTEGER NOT NULL,CHECK(last_sequence>=first_sequence),CHECK(event_to_us>=event_from_us),CHECK(received_to_us>=received_from_us)) STRICT;
CREATE TABLE snapshots(snapshot_id TEXT PRIMARY KEY,account_id TEXT NOT NULL REFERENCES accounts(account_id),release_hash TEXT NOT NULL REFERENCES release_bundles(release_hash),candle_close_us INTEGER NOT NULL,knowledge_cutoff_us INTEGER NOT NULL,field_hash TEXT NOT NULL CHECK(length(field_hash)=64),state_json TEXT NOT NULL CHECK(json_valid(state_json)),tokenizer_hash TEXT CHECK(length(tokenizer_hash)=64),token_count INTEGER CHECK(token_count BETWEEN 0 AND 399),lineage_hash TEXT NOT NULL CHECK(length(lineage_hash)=64),account_revision TEXT NOT NULL CHECK(json_valid(account_revision)),valid INTEGER NOT NULL CHECK(valid IN (0,1)),invalid_reason TEXT,recorded_at_us INTEGER NOT NULL,CHECK(knowledge_cutoff_us>=candle_close_us),CHECK(valid=0 OR (tokenizer_hash IS NOT NULL AND token_count IS NOT NULL))) STRICT;
CREATE TABLE snapshot_inputs(snapshot_id TEXT NOT NULL REFERENCES snapshots(snapshot_id),line_no INTEGER NOT NULL CHECK(line_no>=0),event_id TEXT REFERENCES source_events(event_id),segment_hash TEXT REFERENCES event_segments(segment_hash),sequence_from INTEGER,sequence_to INTEGER,recorded_at_us INTEGER NOT NULL,PRIMARY KEY(snapshot_id,line_no),CHECK((event_id IS NULL)!=(segment_hash IS NULL)),CHECK(sequence_to IS NULL OR sequence_from IS NOT NULL AND sequence_to>=sequence_from)) STRICT;
CREATE TABLE decisions(decision_id TEXT PRIMARY KEY,snapshot_id TEXT NOT NULL REFERENCES snapshots(snapshot_id),request_id TEXT NOT NULL UNIQUE,deadline_us INTEGER NOT NULL,model_id TEXT NOT NULL,response_json TEXT CHECK(json_valid(response_json)),response_hash TEXT CHECK(length(response_hash)=64),status TEXT NOT NULL CHECK(status IN ('pending','completed','rejected','hold','timeout')),reason TEXT,received_at_us INTEGER,recorded_at_us INTEGER NOT NULL,UNIQUE(snapshot_id,request_id)) STRICT;
CREATE TABLE candidate_results(decision_id TEXT NOT NULL REFERENCES decisions(decision_id),candidate_id INTEGER NOT NULL CHECK(candidate_id BETWEEN 1 AND 6),status TEXT NOT NULL CHECK(status IN ('eligible','hold','rejected','excluded')),normalized_json TEXT CHECK(json_valid(normalized_json)),veto_codes_json TEXT NOT NULL CHECK(json_valid(veto_codes_json)),recorded_at_us INTEGER NOT NULL,PRIMARY KEY(decision_id,candidate_id)) STRICT;
CREATE TABLE order_intents(intent_id TEXT PRIMARY KEY,account_id TEXT NOT NULL REFERENCES accounts(account_id),decision_id TEXT REFERENCES decisions(decision_id),candidate_id INTEGER NOT NULL CHECK(candidate_id BETWEEN 1 AND 6),release_hash TEXT NOT NULL REFERENCES release_bundles(release_hash),candle_close_us INTEGER NOT NULL,action_slot TEXT NOT NULL,instrument TEXT NOT NULL,side TEXT NOT NULL CHECK(side IN ('buy','sell')),qty TEXT NOT NULL,limit_price TEXT NOT NULL,max_fee_usd_u INTEGER NOT NULL CHECK(max_fee_usd_u>=0),client_order_id TEXT NOT NULL UNIQUE,state TEXT NOT NULL CHECK(state IN ('reserved','dispatching','open','partial','filled','canceled','rejected','unknown')),venue_order_id TEXT,permit_epoch INTEGER NOT NULL,generation INTEGER NOT NULL,version INTEGER NOT NULL CHECK(version>=0),proposal_json TEXT NOT NULL CHECK(json_valid(proposal_json)),prepared_revision_json TEXT NOT NULL CHECK(json_valid(prepared_revision_json)),recorded_at_us INTEGER NOT NULL,UNIQUE(account_id,candle_close_us,candidate_id,action_slot)) STRICT;
CREATE TABLE order_events(event_id TEXT PRIMARY KEY,append_sequence INTEGER NOT NULL UNIQUE CHECK(append_sequence>0),intent_id TEXT NOT NULL REFERENCES order_intents(intent_id),kind TEXT NOT NULL CHECK(kind IN ('reserved','dispatching','open','partial','filled','canceled','rejected','unknown')),venue_event_key TEXT UNIQUE,payload_json TEXT NOT NULL CHECK(json_valid(payload_json)),event_at_us INTEGER,received_at_us INTEGER NOT NULL,recorded_at_us INTEGER NOT NULL) STRICT;
CREATE TABLE reservations(intent_id TEXT PRIMARY KEY REFERENCES order_intents(intent_id),cash_usd_u INTEGER NOT NULL CHECK(cash_usd_u>=0),base_qty TEXT NOT NULL,gross_usd_u INTEGER NOT NULL CHECK(gross_usd_u>=0),loss_budget_usd_u INTEGER NOT NULL CHECK(loss_budget_usd_u>=0),remaining_qty TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('reserved','dispatching','open','partial','filled','canceled','rejected','unknown')),version INTEGER NOT NULL CHECK(version>=0),updated_at_us INTEGER NOT NULL) STRICT;
CREATE TABLE fills(fill_id TEXT PRIMARY KEY,account_id TEXT NOT NULL REFERENCES accounts(account_id),intent_id TEXT NOT NULL REFERENCES order_intents(intent_id),venue TEXT NOT NULL,venue_trade_id TEXT NOT NULL,venue_order_id TEXT NOT NULL,instrument TEXT NOT NULL,side TEXT NOT NULL CHECK(side IN ('buy','sell')),base_qty TEXT NOT NULL,quote_qty TEXT NOT NULL,price TEXT NOT NULL,fee_asset TEXT NOT NULL,fee_qty TEXT NOT NULL,event_at_us INTEGER NOT NULL,received_at_us INTEGER NOT NULL,payload_hash TEXT NOT NULL CHECK(length(payload_hash)=64),recorded_at_us INTEGER NOT NULL,UNIQUE(account_id,venue,venue_trade_id)) STRICT;
CREATE TABLE fill_corrections(correction_id TEXT PRIMARY KEY,fill_id TEXT NOT NULL REFERENCES fills(fill_id),previous_payload_hash TEXT NOT NULL CHECK(length(previous_payload_hash)=64),corrected_payload_json TEXT NOT NULL CHECK(json_valid(corrected_payload_json)),corrected_payload_hash TEXT NOT NULL CHECK(length(corrected_payload_hash)=64),venue_revision TEXT,received_at_us INTEGER NOT NULL,reason TEXT NOT NULL,recorded_at_us INTEGER NOT NULL,UNIQUE(fill_id,corrected_payload_hash)) STRICT;
CREATE TABLE journal_transactions(transaction_id TEXT PRIMARY KEY,sequence INTEGER NOT NULL UNIQUE CHECK(sequence>0),account_id TEXT NOT NULL REFERENCES accounts(account_id),source_kind TEXT NOT NULL CHECK(source_kind IN ('journal','fill','correction','transfer','rounding')),source_id TEXT NOT NULL,event_at_us INTEGER NOT NULL,recorded_at_us INTEGER NOT NULL,UNIQUE(account_id,source_kind,source_id)) STRICT;
CREATE TABLE journal_postings(transaction_id TEXT NOT NULL REFERENCES journal_transactions(transaction_id),line_no INTEGER NOT NULL CHECK(line_no>=0),ledger_account TEXT NOT NULL CHECK(length(ledger_account)>0),asset TEXT,native_delta TEXT,usd_delta_u INTEGER NOT NULL,recorded_at_us INTEGER NOT NULL,PRIMARY KEY(transaction_id,line_no),CHECK((asset IS NULL)=(native_delta IS NULL))) STRICT;
CREATE TABLE balance_positions(account_id TEXT NOT NULL REFERENCES accounts(account_id),asset TEXT NOT NULL,native_qty TEXT NOT NULL,cost_basis_usd_u INTEGER NOT NULL CHECK(cost_basis_usd_u>=0),journal_sequence INTEGER NOT NULL CHECK(journal_sequence>=0),version INTEGER NOT NULL CHECK(version>=0),PRIMARY KEY(account_id,asset)) STRICT;
CREATE TABLE equity_marks(mark_id TEXT PRIMARY KEY,account_id TEXT NOT NULL REFERENCES accounts(account_id),lineage_hash TEXT NOT NULL CHECK(length(lineage_hash)=64),equity_usd_u INTEGER NOT NULL,units TEXT NOT NULL,nav TEXT NOT NULL,high_water_nav TEXT NOT NULL,day_open_nav TEXT NOT NULL,drawdown TEXT NOT NULL,daily_loss TEXT NOT NULL,valuation_version INTEGER NOT NULL CHECK(valuation_version>=0),marked_at_us INTEGER NOT NULL,recorded_at_us INTEGER NOT NULL) STRICT;
CREATE TABLE external_flows(flow_id TEXT PRIMARY KEY,account_id TEXT NOT NULL REFERENCES accounts(account_id),venue_transfer_key TEXT NOT NULL,asset TEXT NOT NULL,native_qty TEXT NOT NULL,usd_value_u INTEGER NOT NULL,units_delta TEXT NOT NULL,preflow_mark_id TEXT NOT NULL REFERENCES equity_marks(mark_id),transaction_id TEXT NOT NULL REFERENCES journal_transactions(transaction_id),event_at_us INTEGER NOT NULL,recorded_at_us INTEGER NOT NULL,UNIQUE(account_id,venue_transfer_key)) STRICT;
CREATE TABLE forecasts(forecast_id TEXT PRIMARY KEY,decision_id TEXT NOT NULL REFERENCES decisions(decision_id),candidate_id INTEGER NOT NULL CHECK(candidate_id BETWEEN 1 AND 6),side TEXT NOT NULL CHECK(side IN ('buy','sell')),horizon_candles INTEGER NOT NULL CHECK(horizon_candles>0),probabilities_json TEXT NOT NULL CHECK(json_valid(probabilities_json)),calibrated_p TEXT,calibrator_hash TEXT CHECK(length(calibrator_hash)=64),eligibility INTEGER NOT NULL CHECK(eligibility IN (0,1)),execution_policy_hash TEXT NOT NULL CHECK(length(execution_policy_hash)=64),recorded_at_us INTEGER NOT NULL,UNIQUE(decision_id,candidate_id,side,execution_policy_hash)) STRICT;
CREATE TABLE outcome_labels(label_id TEXT PRIMARY KEY,forecast_id TEXT NOT NULL REFERENCES forecasts(forecast_id),label_version INTEGER NOT NULL CHECK(label_version>=0),maturity_us INTEGER NOT NULL,resolved_at_us INTEGER,status TEXT NOT NULL CHECK(status IN ('pending','resolved','unresolvable','corrected')),net_return TEXT,outcome INTEGER CHECK(outcome IN (0,1)),execution_manifest_hash TEXT CHECK(length(execution_manifest_hash)=64),missing_reason TEXT,version INTEGER NOT NULL CHECK(version>=0),UNIQUE(forecast_id,label_version),CHECK(status NOT IN ('resolved','corrected') OR (outcome IS NOT NULL AND resolved_at_us IS NOT NULL AND execution_manifest_hash IS NOT NULL))) STRICT;
CREATE TABLE label_events(label_event_id TEXT PRIMARY KEY,label_id TEXT NOT NULL REFERENCES outcome_labels(label_id),revision INTEGER NOT NULL CHECK(revision>=0),previous_event_id TEXT REFERENCES label_events(label_event_id),kind TEXT NOT NULL CHECK(kind IN ('pending','resolved','unresolvable','corrected')),payload_json TEXT NOT NULL CHECK(json_valid(payload_json)),payload_hash TEXT NOT NULL CHECK(length(payload_hash)=64),recorded_at_us INTEGER NOT NULL,UNIQUE(label_id,revision)) STRICT;
CREATE TABLE evidence_manifests(manifest_hash TEXT PRIMARY KEY CHECK(length(manifest_hash)=64),candidate_id INTEGER NOT NULL CHECK(candidate_id BETWEEN 1 AND 6),observations_json TEXT NOT NULL CHECK(json_valid(observations_json)),methodology_hash TEXT NOT NULL CHECK(length(methodology_hash)=64),cutoff_us INTEGER NOT NULL,expires_at_us INTEGER NOT NULL,eligibility INTEGER NOT NULL CHECK(eligibility IN (0,1)),missing_fields_json TEXT NOT NULL CHECK(json_valid(missing_fields_json)),recorded_at_us INTEGER NOT NULL) STRICT;
CREATE TABLE review_sessions(session_id TEXT PRIMARY KEY,account_id TEXT NOT NULL REFERENCES accounts(account_id),cutoff_us INTEGER NOT NULL,reconcile_id TEXT NOT NULL REFERENCES reconciliations(reconcile_id),manifest_hash TEXT NOT NULL CHECK(length(manifest_hash)=64),status TEXT NOT NULL CHECK(status IN ('pending','completed','rejected')),archive_json TEXT NOT NULL CHECK(json_valid(archive_json)),export_json TEXT NOT NULL CHECK(json_valid(export_json)),recorded_at_us INTEGER NOT NULL,UNIQUE(account_id,cutoff_us)) STRICT;
CREATE TABLE review_jobs(job_id TEXT PRIMARY KEY,dedupe_key TEXT NOT NULL UNIQUE,kind TEXT NOT NULL,session_id TEXT REFERENCES review_sessions(session_id),snapshot_id TEXT REFERENCES snapshots(snapshot_id),decision_id TEXT REFERENCES decisions(decision_id),status TEXT NOT NULL CHECK(status IN ('pending','completed','rejected')),payload_hash TEXT NOT NULL CHECK(length(payload_hash)=64),attempts INTEGER NOT NULL CHECK(attempts>=0),next_attempt_us INTEGER,job_json TEXT NOT NULL CHECK(json_valid(job_json)),recorded_at_us INTEGER NOT NULL) STRICT;
CREATE TABLE candidate_control(account_id TEXT NOT NULL REFERENCES accounts(account_id),candidate_id INTEGER NOT NULL CHECK(candidate_id BETWEEN 1 AND 6),review_paused INTEGER NOT NULL CHECK(review_paused IN (0,1)),review_job_id TEXT REFERENCES review_jobs(job_id),incident_epoch INTEGER NOT NULL CHECK(incident_epoch>=0),version INTEGER NOT NULL CHECK(version>=0),PRIMARY KEY(account_id,candidate_id)) STRICT;
CREATE TABLE release_events(event_id TEXT PRIMARY KEY,release_hash TEXT NOT NULL REFERENCES release_bundles(release_hash),kind TEXT NOT NULL CHECK(kind IN ('approval','rejection','activation','rollback')),actor TEXT NOT NULL,evidence_hash TEXT NOT NULL CHECK(length(evidence_hash)=64),recorded_at_us INTEGER NOT NULL) STRICT;
CREATE TABLE evaluation_runs(run_id TEXT PRIMARY KEY,release_hash TEXT NOT NULL REFERENCES release_bundles(release_hash),dataset_manifest_hash TEXT NOT NULL CHECK(length(dataset_manifest_hash)=64),split_manifest_hash TEXT NOT NULL CHECK(length(split_manifest_hash)=64),holdout_id TEXT NOT NULL,metrics_json TEXT NOT NULL CHECK(json_valid(metrics_json)),status TEXT NOT NULL CHECK(status IN ('pending','completed','rejected')),recorded_at_us INTEGER NOT NULL) STRICT;
CREATE INDEX source_causal ON source_events(source,stream,logical_key,known_at_us);
CREATE INDEX source_receipt ON source_events(event_at_us,received_at_us);
CREATE INDEX intents_account_state ON order_intents(account_id,state);
CREATE INDEX fills_account_event ON fills(account_id,event_at_us);
CREATE INDEX outcomes_maturity ON outcome_labels(status,maturity_us);
CREATE INDEX reviews_pending ON review_jobs(status,next_attempt_us);
CREATE INDEX journal_account_sequence ON journal_transactions(account_id,sequence);
CREATE INDEX equity_account_time ON equity_marks(account_id,marked_at_us);
CREATE TRIGGER control_events_no_update BEFORE UPDATE ON control_events BEGIN SELECT RAISE(ABORT,'append-only control_events'); END;
CREATE TRIGGER control_events_no_delete BEFORE DELETE ON control_events BEGIN SELECT RAISE(ABORT,'append-only control_events'); END;
CREATE TRIGGER source_events_no_update BEFORE UPDATE ON source_events BEGIN SELECT RAISE(ABORT,'append-only source_events'); END;
CREATE TRIGGER source_events_no_delete BEFORE DELETE ON source_events BEGIN SELECT RAISE(ABORT,'append-only source_events'); END;
CREATE TRIGGER source_invalidations_no_update BEFORE UPDATE ON source_invalidations BEGIN SELECT RAISE(ABORT,'append-only source_invalidations'); END;
CREATE TRIGGER source_invalidations_no_delete BEFORE DELETE ON source_invalidations BEGIN SELECT RAISE(ABORT,'append-only source_invalidations'); END;
CREATE TRIGGER event_segments_no_update BEFORE UPDATE ON event_segments BEGIN SELECT RAISE(ABORT,'append-only event_segments'); END;
CREATE TRIGGER event_segments_no_delete BEFORE DELETE ON event_segments BEGIN SELECT RAISE(ABORT,'append-only event_segments'); END;
CREATE TRIGGER snapshots_no_update BEFORE UPDATE ON snapshots BEGIN SELECT RAISE(ABORT,'append-only snapshots'); END;
CREATE TRIGGER snapshots_no_delete BEFORE DELETE ON snapshots BEGIN SELECT RAISE(ABORT,'append-only snapshots'); END;
CREATE TRIGGER snapshot_inputs_no_update BEFORE UPDATE ON snapshot_inputs BEGIN SELECT RAISE(ABORT,'append-only snapshot_inputs'); END;
CREATE TRIGGER snapshot_inputs_no_delete BEFORE DELETE ON snapshot_inputs BEGIN SELECT RAISE(ABORT,'append-only snapshot_inputs'); END;
CREATE TRIGGER decisions_no_update BEFORE UPDATE ON decisions BEGIN SELECT RAISE(ABORT,'append-only decisions'); END;
CREATE TRIGGER decisions_no_delete BEFORE DELETE ON decisions BEGIN SELECT RAISE(ABORT,'append-only decisions'); END;
CREATE TRIGGER candidate_results_no_update BEFORE UPDATE ON candidate_results BEGIN SELECT RAISE(ABORT,'append-only candidate_results'); END;
CREATE TRIGGER candidate_results_no_delete BEFORE DELETE ON candidate_results BEGIN SELECT RAISE(ABORT,'append-only candidate_results'); END;
CREATE TRIGGER order_events_no_update BEFORE UPDATE ON order_events BEGIN SELECT RAISE(ABORT,'append-only order_events'); END;
CREATE TRIGGER order_events_no_delete BEFORE DELETE ON order_events BEGIN SELECT RAISE(ABORT,'append-only order_events'); END;
CREATE TRIGGER fills_no_update BEFORE UPDATE ON fills BEGIN SELECT RAISE(ABORT,'append-only fills'); END;
CREATE TRIGGER fills_no_delete BEFORE DELETE ON fills BEGIN SELECT RAISE(ABORT,'append-only fills'); END;
CREATE TRIGGER fill_corrections_no_update BEFORE UPDATE ON fill_corrections BEGIN SELECT RAISE(ABORT,'append-only fill_corrections'); END;
CREATE TRIGGER fill_corrections_no_delete BEFORE DELETE ON fill_corrections BEGIN SELECT RAISE(ABORT,'append-only fill_corrections'); END;
CREATE TRIGGER journal_transactions_no_update BEFORE UPDATE ON journal_transactions BEGIN SELECT RAISE(ABORT,'append-only journal_transactions'); END;
CREATE TRIGGER journal_transactions_no_delete BEFORE DELETE ON journal_transactions BEGIN SELECT RAISE(ABORT,'append-only journal_transactions'); END;
CREATE TRIGGER journal_postings_no_update BEFORE UPDATE ON journal_postings BEGIN SELECT RAISE(ABORT,'append-only journal_postings'); END;
CREATE TRIGGER journal_postings_no_delete BEFORE DELETE ON journal_postings BEGIN SELECT RAISE(ABORT,'append-only journal_postings'); END;
CREATE TRIGGER equity_marks_no_update BEFORE UPDATE ON equity_marks BEGIN SELECT RAISE(ABORT,'append-only equity_marks'); END;
CREATE TRIGGER equity_marks_no_delete BEFORE DELETE ON equity_marks BEGIN SELECT RAISE(ABORT,'append-only equity_marks'); END;
CREATE TRIGGER external_flows_no_update BEFORE UPDATE ON external_flows BEGIN SELECT RAISE(ABORT,'append-only external_flows'); END;
CREATE TRIGGER external_flows_no_delete BEFORE DELETE ON external_flows BEGIN SELECT RAISE(ABORT,'append-only external_flows'); END;
CREATE TRIGGER reconciliations_no_update BEFORE UPDATE ON reconciliations BEGIN SELECT RAISE(ABORT,'append-only reconciliations'); END;
CREATE TRIGGER reconciliations_no_delete BEFORE DELETE ON reconciliations BEGIN SELECT RAISE(ABORT,'append-only reconciliations'); END;
CREATE TRIGGER forecasts_no_update BEFORE UPDATE ON forecasts BEGIN SELECT RAISE(ABORT,'append-only forecasts'); END;
CREATE TRIGGER forecasts_no_delete BEFORE DELETE ON forecasts BEGIN SELECT RAISE(ABORT,'append-only forecasts'); END;
CREATE TRIGGER label_events_no_update BEFORE UPDATE ON label_events BEGIN SELECT RAISE(ABORT,'append-only label_events'); END;
CREATE TRIGGER label_events_no_delete BEFORE DELETE ON label_events BEGIN SELECT RAISE(ABORT,'append-only label_events'); END;
CREATE TRIGGER evidence_manifests_no_update BEFORE UPDATE ON evidence_manifests BEGIN SELECT RAISE(ABORT,'append-only evidence_manifests'); END;
CREATE TRIGGER evidence_manifests_no_delete BEFORE DELETE ON evidence_manifests BEGIN SELECT RAISE(ABORT,'append-only evidence_manifests'); END;
CREATE TRIGGER review_sessions_no_update BEFORE UPDATE ON review_sessions BEGIN SELECT RAISE(ABORT,'append-only review_sessions'); END;
CREATE TRIGGER review_sessions_no_delete BEFORE DELETE ON review_sessions BEGIN SELECT RAISE(ABORT,'append-only review_sessions'); END;
CREATE TRIGGER review_jobs_no_update BEFORE UPDATE ON review_jobs BEGIN SELECT RAISE(ABORT,'append-only review_jobs'); END;
CREATE TRIGGER review_jobs_no_delete BEFORE DELETE ON review_jobs BEGIN SELECT RAISE(ABORT,'append-only review_jobs'); END;
CREATE TRIGGER release_bundles_no_update BEFORE UPDATE ON release_bundles BEGIN SELECT RAISE(ABORT,'append-only release_bundles'); END;
CREATE TRIGGER release_bundles_no_delete BEFORE DELETE ON release_bundles BEGIN SELECT RAISE(ABORT,'append-only release_bundles'); END;
CREATE TRIGGER release_events_no_update BEFORE UPDATE ON release_events BEGIN SELECT RAISE(ABORT,'append-only release_events'); END;
CREATE TRIGGER release_events_no_delete BEFORE DELETE ON release_events BEGIN SELECT RAISE(ABORT,'append-only release_events'); END;
CREATE TRIGGER evaluation_runs_no_update BEFORE UPDATE ON evaluation_runs BEGIN SELECT RAISE(ABORT,'append-only evaluation_runs'); END;
CREATE TRIGGER evaluation_runs_no_delete BEFORE DELETE ON evaluation_runs BEGIN SELECT RAISE(ABORT,'append-only evaluation_runs'); END;
CREATE TRIGGER intent_identity_immutable BEFORE UPDATE OF intent_id,account_id,decision_id,candidate_id,release_hash,candle_close_us,action_slot,instrument,side,qty,limit_price,max_fee_usd_u,client_order_id,permit_epoch,generation,proposal_json,prepared_revision_json,recorded_at_us ON order_intents BEGIN SELECT RAISE(ABORT,'immutable intent identity'); END;
CREATE TRIGGER intent_no_delete BEFORE DELETE ON order_intents BEGIN SELECT RAISE(ABORT,'retained intent'); END;

-- Cutoff-proven revision/generation snapshots recorded within each outer commit.
CREATE TABLE account_revision_history(append_sequence INTEGER PRIMARY KEY AUTOINCREMENT,account_id TEXT NOT NULL REFERENCES accounts(account_id),journal_sequence INTEGER NOT NULL CHECK(journal_sequence>=0),version INTEGER NOT NULL CHECK(version>=0),generation INTEGER NOT NULL CHECK(generation>=0),evidence_watermarks_json TEXT NOT NULL CHECK(json_valid(evidence_watermarks_json)),known_at_us INTEGER NOT NULL CHECK(known_at_us>=recorded_at_us),recorded_at_us INTEGER NOT NULL) STRICT;
CREATE INDEX account_revision_cutoff ON account_revision_history(account_id,known_at_us,append_sequence);
CREATE TRIGGER account_revision_history_no_update BEFORE UPDATE ON account_revision_history BEGIN SELECT RAISE(ABORT,'append-only account_revision_history'); END;
CREATE TRIGGER account_revision_history_no_delete BEFORE DELETE ON account_revision_history BEGIN SELECT RAISE(ABORT,'append-only account_revision_history'); END;
